class Solution { public int maximumPoints(int[][] edges,int[] coins,int k){int n=coins.length;List<Integer>[] graph=new List[n];for(int node=0;node<n;node++)graph[node]=new ArrayList<>();for(int[] edge:edges){graph[edge[0]].add(edge[1]);graph[edge[1]].add(edge[0]);}int[] parent=new int[n],order=new int[n];Arrays.fill(parent,-2);parent[0]=-1;Deque<Integer> stack=new ArrayDeque<>();stack.addLast(0);int size=0;while(!stack.isEmpty()){int node=stack.removeLast();order[size++]=node;for(int next:graph[node])if(next!=parent[node]){parent[next]=node;stack.addLast(next);}}final int MAX_SHIFT=14,STATES=15;int[][] dp=new int[n][STATES];for(int index=size-1;index>=0;index--){int node=order[index];for(int shift=MAX_SHIFT;shift>=0;shift--){int nextShift=Math.min(MAX_SHIFT,shift+1);int first=(coins[node]>>shift)-k,second=coins[node]>>nextShift;for(int next:graph[node])if(parent[next]==node){first+=dp[next][shift];second+=dp[next][nextShift];}dp[node][shift]=Math.max(first,second);}}return dp[0][0];} }
